// Registry is the in-memory cache of module configs, loaded once at Open.
// Since SetBindingOptions (the first mutation path) the ordered/byID maps are
// guarded by mu: Get/List take the read side, the write path takes the write
// side and refreshes both under it — the maps are built in Open before the
// Registry escapes, so until the first write they are effectively immutable,
// and readers keep their exact cache-only behavior.
type Registry struct {
	mu      sync.RWMutex
	ordered []Module
	byID    map[string]Module
	s       *store.Store // the write path's database handle (captured at Open)
}

// Module is one module config entity. media_type is a string the core carries
// and never branches on. IdentityFields is the module's presentation
// declaration (element-pages D-1): the mandatory identity-block fields, in
// declared order — config data the SPA serves and renders, never core logic.
type Module struct {
	ID                  string
	MediaType           string
	SchemaVersion       int
	IdentityFields      []string                // mandatory identity block, declared order
	ItemName            string                  // display.item_name element-naming template (display-naming), decoded verbatim — config data, never core logic
	TitleSourcePriority []string                // display.title_source_priority (plugin-title-enrichment): the config-ordered title walk — Go-consumed view input
	LanguagePreference  []string                // display.language_preference: the display-language pick order — Go-consumed view input
	Scanner             ScannerBinding          // scan-side capability slot
	MetadataSources     []MetadataSourceBinding // enrichment chain, config order
}

// ScannerBinding is the scanner capability slot a module binds: which plugin
// serves it, which capability id, the ordered display_fields declaration (the
// footer render order for this parser's namespace — element-pages D-1), and
// the opaque options forwarded to every scan RPC.
type ScannerBinding struct {
	PluginID      string
	CapabilityID  string
	DisplayFields []string
	Options       json.RawMessage
}

// MetadataSourceBinding is one enrichment-source config slot: which plugin +
// capability serves it, its chain priority (lower runs first), whether it is
// active, its auth mode (opaque config string; Phase B interprets SERVER /
// CLIENT), the ordered display_fields declaration (footer render order —
// element-pages D-1), and the opaque options forwarded to its RPCs. Core
// selection reads this slice from config and never branches on media type
// (AC-4).
type MetadataSourceBinding struct {
	PluginID      string
	CapabilityID  string
	Priority      int
	Enabled       bool
	AuthMode      string
	DisplayFields []string
	Options       json.RawMessage
}

// Open seeds the built-in module configs (tv, image, serial — idempotent), then
// loads every enabled module config from the modules table into an in-memory
// cache. Get/List after this are pure (no database access).
func Open(ctx context.Context, s *store.Store) (*Registry, error) {
	db := s.DB()
	if _, err := db.ExecContext(ctx, seedModulesSQL,
		"tv", "tv", tvConfigJSON, 2, 1, seedCreatedAt, seedCreatedAt,
	); err != nil {
		return nil, fmt.Errorf("module: seed: %w", err)
	}
	// v1→v2 promotion for stores seeded before the frame-grabber binding
	// existed (D-7): the INSERT OR IGNORE above is a no-op on them, this
	// UPDATE is the actual migration (same params, deterministic timestamp).
	if _, err := db.ExecContext(ctx, upgradeTVConfigSQL, tvConfigJSON, seedCreatedAt); err != nil {
		return nil, fmt.Errorf("module: upgrade tv v2: %w", err)
	}
	// Second idempotent seed: the image module (base-scanner + image-enricher).
	// modules.media_type UNIQUE accepts "image" (distinct from "tv"); INSERT OR
	// IGNORE makes Open safe to run repeatedly (no error, no duplicate rows).
	if _, err := db.ExecContext(ctx, seedModulesSQL,
		"image", "image", imageConfigJSON, 1, 1, seedCreatedAt, seedCreatedAt,
	); err != nil {
		return nil, fmt.Errorf("module: seed image: %w", err)
	}
	// Third idempotent seed: the serial module (serial-scanner + serial-parser +
	// frame-grabber + shikimori + tmdb, serials-library design.md §Interfaces §8
	// — mirrors the tv seed shape). INSERT OR IGNORE keeps the tv/image rows
	// byte-identical and Open safe to run repeatedly.
	if _, err := db.ExecContext(ctx, seedModulesSQL,
		"serial", "serial", serialConfigJSON, 4, 1, seedCreatedAt, seedCreatedAt,
	); err != nil {
		return nil, fmt.Errorf("module: seed serial: %w", err)
	}
	// v1→v2 promotion (enrichment D-7) — the tv upgrade's mechanism, scoped
	// to the serial row.
	if _, err := db.ExecContext(ctx, upgradeSerialConfigSQL, serialConfigJSON, seedCreatedAt); err != nil {
		return nil, fmt.Errorf("module: upgrade serial v2: %w", err)
	}
	// v2→v3 promotion (display-naming) — the chain step after the v2 promotion.
	if _, err := db.ExecContext(ctx, upgradeSerialConfigV3SQL, serialConfigJSON, seedCreatedAt); err != nil {
		return nil, fmt.Errorf("module: upgrade serial v3: %w", err)
	}
	// v3→v4 promotion (tmdb-enrichment D7) — the chain step after the v3
	// promotion.
	if _, err := db.ExecContext(ctx, upgradeSerialConfigV4SQL, serialConfigJSON, seedCreatedAt); err != nil {
		return nil, fmt.Errorf("module: upgrade serial v4: %w", err)
	}
	rows, err := db.QueryContext(ctx, listModulesSQL)
	if err != nil {
		return nil, fmt.Errorf("module: load: %w", err)
	}
	defer rows.Close()

	r := &Registry{s: s, byID: make(map[string]Module)}
	for rows.Next() {
		var (
			id            string
			mediaType     string
			configBytes   []byte
			schemaVersion int
		)
		if err := rows.Scan(&id, &mediaType, &configBytes, &schemaVersion); err != nil {
			return nil, fmt.Errorf("module: load scan: %w", err)
		}
		m, err := parseModule(id, mediaType, schemaVersion, configBytes)
		if err != nil {
			return nil, err
		}
		r.ordered = append(r.ordered, m)
		r.byID[m.ID] = m
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("module: load: %w", err)
	}
	return r, nil
}

// Get returns the cached module by id (cache-only — pure). An unknown id yields
// a wrapped errNotFound (no nil dereference). The read side of mu: safe
// concurrent with SetBindingOptions' write-side cache refresh.
func (r *Registry) Get(moduleID string) (Module, error) {
	r.mu.RLock()
	defer r.mu.RUnlock()
	m, ok := r.byID[moduleID]
	if !ok {
		return Module{}, fmt.Errorf("module %q: %w", moduleID, errNotFound)
	}
	return m, nil
}

// List returns a defensive copy of all enabled modules in id order
// (cache-only — pure). The read side of mu: safe concurrent with
// SetBindingOptions' write-side cache refresh.
func (r *Registry) List() ([]Module, error) {
	r.mu.RLock()
	defer r.mu.RUnlock()
	out := make([]Module, len(r.ordered))
	copy(out, r.ordered)
	return out, nil
}

// SetBindingOptions rewrites ONE metadata-source binding's options inside a
// module row's config_json — the Registry's FIRST mutation path. The raw row
// is read, only the target binding's options value span is spliced (schema
// and every sibling binding byte-untouched), one guarded UPDATE persists it,
// and the in-memory cache is refreshed under the SAME write lock in the SAME
// call — so derivation, the chain, and api handlers reading through Get/List
// see the new options immediately, with no unsynchronized map access (a
// lock-free refresh here would be a fatal concurrent-map error under live
// traffic).
//
// Refusals: unknown module id → wrapped errNotFound (api maps 404); a plugin
// the module does not bind as a metadata_source → wrapped errUnknownSource
// (api maps 400). Options are stored verbatim — serve-side redaction is the
// api's concern, not the store's.
func (r *Registry) SetBindingOptions(ctx context.Context, moduleID, pluginID string, options json.RawMessage) error {
	if !json.Valid(options) {
		return fmt.Errorf("module %q source %q options: not valid JSON", moduleID, pluginID)
	}
	r.mu.Lock()
	defer r.mu.Unlock()

	// Read-before-write from the row itself (the cache carries no raw config
	// bytes). The row must exist: the unknown-module refusal.
	var (
		mediaType     string
		schemaVersion int
		config        []byte
	)
	err := r.s.DB().QueryRowContext(ctx, selectModuleRowSQL, moduleID).
		Scan(&mediaType, &schemaVersion, &config)
	if err != nil {
		if err == sql.ErrNoRows {
			return fmt.Errorf("module %q: %w", moduleID, errNotFound)
		}
		return fmt.Errorf("module %q: load row: %w", moduleID, err)
	}

	// Splice: rewrite ONLY the target binding's options value inside the raw
	// config. An unbound plugin is refused here, before anything is written.
	config, err = rewriteBindingOptions(config, pluginID, options)
	if err != nil {
		return fmt.Errorf("module %q source %q: %w", moduleID, pluginID, err)
	}

	res, err := r.s.DB().ExecContext(ctx, setBindingOptionsSQL, config, moduleID)
	if err != nil {
		return fmt.Errorf("module %q: update config: %w", moduleID, err)
	}
	if n, err := res.RowsAffected(); err == nil && n != 1 {
		return fmt.Errorf("module %q: update config: %d rows affected, want 1", moduleID, n)
	}

	// Refresh the cache under the same lock the write holds: re-parse the
	// rewritten config and swap both indexes' entry for this module.
	m, err := parseModule(moduleID, mediaType, schemaVersion, config)
	if err != nil {
		return err
	}
	r.byID[moduleID] = m
	for i := range r.ordered {
		if r.ordered[i].ID == moduleID {
			r.ordered[i] = m
			break
		}
	}
	return nil
}

// IdentityFields returns a defensive copy of the module's declared
// identity_fields (cache-only — pure). Unknown module id → wrapped errNotFound.
func (r *Registry) IdentityFields(moduleID string) ([]string, error) {
	m, err := r.Get(moduleID)
	if err != nil {
		return nil, err
	}
	out := make([]string, len(m.IdentityFields))
	copy(out, m.IdentityFields)
	return out, nil
}

// DisplayFields returns a defensive copy of the declared display_fields order
// for one parser binding (scanner or metadata_source) within a module
// (cache-only — pure). The binding is looked up by plugin id across both slot
// kinds; unknown module or unbound plugin → wrapped errNotFound. A bound
// parser without a display_fields declaration yields an empty slice (the
// seeded-but-unloaded slot-group case: pill only).
func (r *Registry) DisplayFields(moduleID, pluginID string) ([]string, error) {
	m, err := r.Get(moduleID)
	if err != nil {
		return nil, err
	}
	if m.Scanner.PluginID == pluginID {
		return copyFields(m.Scanner.DisplayFields), nil
	}
	for _, src := range m.MetadataSources {
		if src.PluginID == pluginID {
			return copyFields(src.DisplayFields), nil
		}
	}
	return nil, fmt.Errorf("module %q parser %q: %w", moduleID, pluginID, errNotFound)
}

// copyFields clones a declared-field slice so callers can never alias registry
// state. Test helper grade: nil-safe.
func copyFields(src []string) []string {
	out := make([]string, len(src))
	copy(out, src)
	return out
}

// rewriteBindingOptions returns config with ONLY the options value of the
// metadata_sources binding whose plugin_id matches pluginID replaced by
// options. A byte-offset walk (json.Decoder.InputOffset) locates the exact
// value span to splice, so schema_version, the display block, and every
// sibling binding are copied byte-identical — a whole-document re-marshal
// would compact whitespace and reorder keys, touching bytes it must not.
// A config with no such metadata_source binding yields errUnknownSource
// (wrapped — the caller decides the wire shape).
func rewriteBindingOptions(config []byte, pluginID string, options []byte) ([]byte, error) {
	dec := json.NewDecoder(bytes.NewReader(config))
	if tok, err := dec.Token(); err != nil {
		return nil, fmt.Errorf("walk config: %w", err)
	} else if d, ok := tok.(json.Delim); !ok || d != '{' {
		return nil, fmt.Errorf("walk config: not a JSON object")
	}
	for dec.More() {
		keyTok, err := dec.Token()
		if err != nil {
			return nil, fmt.Errorf("walk config: %w", err)
		}
		if keyTok.(string) != "metadata_sources" {
			// Skip any other top-level key (RawMessage decode consumes the
			// whole value without modeling it).
			var skip json.RawMessage
			if err := dec.Decode(&skip); err != nil {
				return nil, fmt.Errorf("walk config: %w", err)
			}
			continue
		}
		if _, err := dec.Token(); err != nil { // the '['
			return nil, fmt.Errorf("walk config: %w", err)
		}
		for dec.More() {
			elemStart := dec.InputOffset()
			// The offset after the previous element parks on the separator
			// (',', whitespace) rather than the element's own '{' — advance to
			// the brace so the element span handed to the splice is exact.
			for elemStart < int64(len(config)) &&
				(isJSONSpace(config[elemStart]) || config[elemStart] == ',') {
				elemStart++
			}
			var probe struct {
				PluginID string `json:"plugin_id"`
			}
			if err := dec.Decode(&probe); err != nil {
				return nil, fmt.Errorf("walk config: metadata_source element: %w", err)
			}
			elemEnd := dec.InputOffset()
			if probe.PluginID != pluginID {
				continue
			}
			out, err := spliceOptionsValue(config, elemStart, elemEnd, options)
			if err != nil {
				return nil, fmt.Errorf("walk config: metadata_source %q: %w", pluginID, err)
			}
			return out, nil
		}
		// The chain exists but binds no such plugin: the 400 refusal.
		return nil, errUnknownSource
	}
	// No metadata_sources key at all: the module binds nothing — same refusal.
	return nil, errUnknownSource
}

// isJSONSpace reports whether b is JSON insignificant whitespace.
func isJSONSpace(b byte) bool {
	return b == ' ' || b == '\t' || b == '\n' || b == '\r'
}

// spliceOptionsValue replaces the options value inside the JSON object spanning
// config[objStart:objEnd] with options. A missing options key is legal config
// shape in principle, so the new pair is appended before the object's closing
// brace rather than refused.
func spliceOptionsValue(config []byte, objStart, objEnd int64, options []byte) ([]byte, error) {
	obj := config[objStart:objEnd]
	dec := json.NewDecoder(bytes.NewReader(obj))
	if tok, err := dec.Token(); err != nil {
		return nil, err
	} else if d, ok := tok.(json.Delim); !ok || d != '{' {
		return nil, fmt.Errorf("binding is not a JSON object")
	}
	for dec.More() {
		keyTok, err := dec.Token()
		if err != nil {
			return nil, err
		}
		// InputOffset parks just after the key token — before the colon — so
		// the value's first byte is found by skipping whitespace, the ':', and
		// whitespace again.
		rel := dec.InputOffset()
		for rel < int64(len(obj)) && isJSONSpace(obj[rel]) {
			rel++
		}
		if rel >= int64(len(obj)) || obj[rel] != ':' {
			return nil, fmt.Errorf("binding key %v: no colon follows", keyTok)
		}
		rel++
		for rel < int64(len(obj)) && isJSONSpace(obj[rel]) {
			rel++
		}
		valStart := rel
		var skip json.RawMessage
		if err := dec.Decode(&skip); err != nil {
			return nil, err
		}
		valEnd := dec.InputOffset() // end of the value token
		if keyTok.(string) != "options" {
			continue
		}
		out := make([]byte, 0, len(config)-int(valEnd-valStart)+len(options))
		out = append(out, config[:objStart+valStart]...)
		out = append(out, options...)
		out = append(out, config[objStart+valEnd:]...)
		return out, nil
	}
	// No options key: append `"options": <value>` before the closing brace.
	insert := objStart + int64(len(obj)) - 1 // the '}' byte
	out := make([]byte, 0, len(config)+len(options)+len(`,"options": `))
	out = append(out, config[:insert]...)
	out = append(out, `, "options": `...)
	out = append(out, options...)
	out = append(out, config[insert:]...)
	return out, nil
}

// parseModule decodes a config_json blob into a Module, extracting the scanner
// slot, the ordered metadata_sources enrichment chain, and the presentation
// declarations (identity_fields per module, display_fields per binding —
// element-pages D-1). The remaining config is intentionally not modeled in Go
// (arch §2.4.2: options are opaque pass-through; module is a config entity,
// not a typed schema) — with THREE display exceptions, the Go-consumed view
// inputs (plugin-title-enrichment): item_name (display-naming) decoded
// verbatim into Module.ItemName, title_source_priority (the config-ordered
// title walk) into Module.TitleSourcePriority, and language_preference (the
// display-language pick order) into Module.LanguagePreference; every other
// display key (rating_source_priority, default_image_source) stays
// SPA-consumed config.
//
// The metadata_sources are modeled verbatim in CONFIG order: Enabled is carried
// (not filtered) so the binding stays lossless; the enrich orchestrator
// (internal/enrich) sorts/runs by Priority and skips disabled sources
// (INV-config-driven, AC-4). The tiebreak for equal priorities is this order.
func parseModule(id, mediaType string, schemaVersion int, configBytes []byte) (Module, error) {
	var cfg struct {
		IdentityFields []string `json:"identity_fields"`
		Display        struct {
			ItemName            string   `json:"item_name"`
			TitleSourcePriority []string `json:"title_source_priority"`
			LanguagePreference  []string `json:"language_preference"`
		} `json:"display"`
		Scanner struct {
			PluginID      string          `json:"plugin_id"`
			CapabilityID  string          `json:"capability_id"`
			DisplayFields []string        `json:"display_fields"`
			Options       json.RawMessage `json:"options"`
		} `json:"scanner"`
		MetadataSources []struct {
			PluginID      string          `json:"plugin_id"`
			CapabilityID  string          `json:"capability_id"`
			Priority      int             `json:"priority"`
			Enabled       bool            `json:"enabled"`
			AuthMode      string          `json:"auth_mode"`
			DisplayFields []string        `json:"display_fields"`
			Options       json.RawMessage `json:"options"`
		} `json:"metadata_sources"`
	}
	if err := json.Unmarshal(configBytes, &cfg); err != nil {
		return Module{}, fmt.Errorf("module %q: parse config_json: %w", id, err)
	}
	m := Module{
		ID:                  id,
		MediaType:           mediaType,
		SchemaVersion:       schemaVersion,
		IdentityFields:      cfg.IdentityFields,
		ItemName:            cfg.Display.ItemName,
		TitleSourcePriority: cfg.Display.TitleSourcePriority,
		LanguagePreference:  cfg.Display.LanguagePreference,
		Scanner: ScannerBinding{
			PluginID:      cfg.Scanner.PluginID,
			CapabilityID:  cfg.Scanner.CapabilityID,
			DisplayFields: cfg.Scanner.DisplayFields,
			Options:       cfg.Scanner.Options,
		},
	}
	m.MetadataSources = make([]MetadataSourceBinding, len(cfg.MetadataSources))
	for i, src := range cfg.MetadataSources {
		m.MetadataSources[i] = MetadataSourceBinding{
			PluginID:      src.PluginID,
			CapabilityID:  src.CapabilityID,
			Priority:      src.Priority,
			Enabled:       src.Enabled,
			AuthMode:      src.AuthMode,
			DisplayFields: src.DisplayFields,
			Options:       src.Options,
		}
	}
	return m, nil
}
